def common_prefix(words: list[str]) -> str:
    if not words:
        return ""

    prefix = words[0]
    for word in words[1:]:
        while not word.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ""
    return prefix

# Example usage:
# print(common_prefix(["flower","flow","flight"]))  # Output: "fl"
# print(common_prefix(["dog","racecar","car"]))  # Output: ""
