def first_missing(nums: list[int]) -> int:
    n = len(nums)
    has_one = False

    # Check if 1 is present in the array
    for num in nums:
        if num == 1:
            has_one = True
            break
    if not has_one:
        return 1

    # Replace negative numbers, zeros, and numbers larger than n with 1s
    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = 1

    # Use index as a hash key and number sign as a presence detector
    for i in range(n):
        index = abs(nums[i]) - 1
        nums[index] = -abs(nums[index])

    # The first positive index + 1 indicates the missing number
    for i in range(n):
        if nums[i] > 0:
            return i + 1

    # If all numbers from 1 to n are present
    return n + 1

# Example usage:
# print(first_missing([1,2,0]))  # Output: 3
# print(first_missing([3,4,-1,1]))  # Output: 2
# print(first_missing([7,8,9,11,12]))  # Output: 1
