from typing import List

def median_two(a: List[int], b: List[int]) -> float:
    if len(a) > len(b):
        a, b = b, a

    x, y = len(a), len(b)
    low, high = 0, x

    while low <= high:
        partition_x = (low + high) // 2
        partition_y = (x + y + 1) // 2 - partition_x

        max_left_x = float('-inf') if partition_x == 0 else a[partition_x - 1]
        min_right_x = float('inf') if partition_x == x else a[partition_x]

        max_left_y = float('-inf') if partition_y == 0 else b[partition_y - 1]
        min_right_y = float('inf') if partition_y == y else b[partition_y]

        if max_left_x <= min_right_y and max_left_y <= min_right_x:
            if (x + y) % 2 == 0:
                return (max(max_left_x, max_left_y) + min(min_right_x, min_right_y)) / 2.0
            else:
                return max(max_left_x, max_left_y)
        elif max_left_x > min_right_y:
            high = partition_x - 1
        else:
            low = partition_x + 1

# Example usage:
# print(median_two([1,3], [2]))  # Output: 2.0
# print(median_two([1,2], [3,4]))  # Output: 2.5
# print(median_two([], [1]))  # Output: 1.0
# print(median_two([1,3,5], [2,4]))  # Output: 3.0
